1	//! Typed, provider-neutral decisions for a managed release pull request.
2	//!
3	//! This is deliberately pre-merge collaboration policy, rather than durable
4	//! release authority. The values name a narrow, credential-free observation
5	//! and the one forge mutation sequence that an executor may perform.
6	//!
7	//! The executor never pushes Git objects directly: on a public repository,
8	//! GitHub's automatic `GITHUB_TOKEN` cannot write to `.github/workflows/*`
9	//! through the Git push protocol or through the forge commit API's own
10	//! `fileChanges`, on any ref. The managed branch is instead updated by
11	//! committing only non-workflow changes onto a deterministic staging branch
12	//! rooted at the current base commit (so it inherits the base's current
13	//! workflow content without writing to that path at all), then moving the
14	//! managed branch's ref onto that commit -- a ref update is not itself a
15	//! write to `.github/workflows/*` and is not subject to the restriction.
16	
17	use base64::engine::general_purpose::STANDARD as BASE64;
18	use base64::Engine as _;
19	use schemars::JsonSchema;
20	use serde::{Deserialize, Deserializer, Serialize};
21	
22	use crate::{CommitSha, GitHubRepository};
23	
24	/// Explicit identity and presentation configuration for one managed release PR.
25	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
26	#[serde(try_from = "ReleasePrConfigWireV1", rename_all = "camelCase", deny_unknown_fields)]
27	pub struct ReleasePrConfigV1 {
28	    pub schema_version: u8,
29	    pub repository: GitHubRepository,
30	    pub base_branch: String,
31	    pub release_branch: String,
32	}
33	
34	impl ReleasePrConfigV1 {
35	    pub const SCHEMA_VERSION: u8 = 1;
36	
37	    pub fn new(
38	        repository: GitHubRepository,
39	        base_branch: String,
40	        release_branch: String,
41	    ) -> Result<Self, ReleasePrDecisionError> {
42	        validate_branch("base branch", &base_branch)?;
43	        validate_branch("managed release branch", &release_branch)?;
44	        Ok(Self {
45	            schema_version: Self::SCHEMA_VERSION,
46	            repository,
47	            base_branch,
48	            release_branch,
49	        })
50	    }
51	
52	    /// The deterministic staging branch this config's release branch commits
53	    /// through before any managed-branch ref is moved.
54	    pub fn staging_branch(&self) -> String {
55	        format!("{}--staging", self.release_branch)
56	    }
57	}
58	
59	/// The on-the-wire shape of [`ReleasePrConfigV1`], before its invariants are checked.
60	///
61	/// Deserializing this (rather than `ReleasePrConfigV1` itself) then calling
62	/// [`ReleasePrConfigV1::from_wire`] keeps a caller's own typed
63	/// [`ReleasePrDecisionError`] (e.g. `E142`) intact -- deserializing straight into
64	/// `ReleasePrConfigV1` still validates, but folds a validation failure into a generic
65	/// `serde` string error, losing the code.
66	#[derive(Clone, Debug, Deserialize, JsonSchema)]
67	#[serde(rename_all = "camelCase", deny_unknown_fields)]
68	pub struct ReleasePrConfigWireV1 {
69	    pub schema_version: u8,
70	    pub repository: GitHubRepository,
71	    pub base_branch: String,
72	    pub release_branch: String,
73	}
74	
75	impl ReleasePrConfigV1 {
76	    /// Validates an already-parsed wire value into a well-formed config.
77	    pub fn from_wire(wire: ReleasePrConfigWireV1) -> Result<Self, ReleasePrDecisionError> {
78	        check_schema_version(wire.schema_version, Self::SCHEMA_VERSION, "release PR configuration")?;
79	        Self::new(wire.repository, wire.base_branch, wire.release_branch)
80	    }
81	}
82	
83	impl TryFrom<ReleasePrConfigWireV1> for ReleasePrConfigV1 {
84	    type Error = ReleasePrDecisionError;
85	
86	    fn try_from(wire: ReleasePrConfigWireV1) -> Result<Self, Self::Error> {
87	        Self::from_wire(wire)
88	    }
89	}
90	
91	/// A credential-free observation supplied by a forge adapter before planning.
92	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
93	#[serde(try_from = "ReleasePrSnapshotWireV2", rename_all = "camelCase", deny_unknown_fields)]
94	pub struct ReleasePrSnapshotV2 {
95	    pub schema_version: u8,
96	    pub repository: GitHubRepository,
97	    pub base_branch: String,
98	    pub base_commit: CommitSha,
99	    pub open_pull_requests: Vec<ReleasePrPullRequestV2>,
100	}
101	
102	impl ReleasePrSnapshotV2 {
103	    pub const SCHEMA_VERSION: u8 = 2;
104	
105	    pub fn new(
106	        repository: GitHubRepository,
107	        base_branch: String,
108	        base_commit: CommitSha,
109	        mut open_pull_requests: Vec<ReleasePrPullRequestV2>,
110	    ) -> Result<Self, ReleasePrDecisionError> {
111	        validate_branch("base branch", &base_branch)?;
112	        let mut numbers = open_pull_requests.iter().map(|pr| pr.number).collect::<Vec<_>>();
113	        numbers.sort_unstable();
114	        if numbers.windows(2).any(|pair| pair[0] == pair[1]) {
115	            return Err(ReleasePrDecisionError::DuplicatePullRequestNumber);
116	        }
117	        open_pull_requests.sort_by_key(|pr| pr.number);
118	        Ok(Self {
119	            schema_version: Self::SCHEMA_VERSION,
120	            repository,
121	            base_branch,
122	            base_commit,
123	            open_pull_requests,
124	        })
125	    }
126	}
127	
128	/// The on-the-wire shape of [`ReleasePrSnapshotV2`], before its invariants are checked.
129	/// See [`ReleasePrConfigWireV1`] for why the CLI deserializes this instead of
130	/// `ReleasePrSnapshotV2` directly.
131	#[derive(Clone, Debug, Deserialize, JsonSchema)]
132	#[serde(rename_all = "camelCase", deny_unknown_fields)]
133	pub struct ReleasePrSnapshotWireV2 {
134	    pub schema_version: u8,
135	    pub repository: GitHubRepository,
136	    pub base_branch: String,
137	    pub base_commit: CommitSha,
138	    pub open_pull_requests: Vec<ReleasePrPullRequestV2>,
139	}
140	
141	impl ReleasePrSnapshotV2 {
142	    /// Validates an already-parsed wire value into a well-formed snapshot.
143	    pub fn from_wire(wire: ReleasePrSnapshotWireV2) -> Result<Self, ReleasePrDecisionError> {
144	        check_schema_version(wire.schema_version, Self::SCHEMA_VERSION, "release PR snapshot")?;
145	        Self::new(
146	            wire.repository,
147	            wire.base_branch,
148	            wire.base_commit,
149	            wire.open_pull_requests,
150	        )
151	    }
152	}
153	
154	impl TryFrom<ReleasePrSnapshotWireV2> for ReleasePrSnapshotV2 {
155	    type Error = ReleasePrDecisionError;
156	
157	    fn try_from(wire: ReleasePrSnapshotWireV2) -> Result<Self, Self::Error> {
158	        Self::from_wire(wire)
159	    }
160	}
161	
162	/// One open pull request observed by a forge adapter.
163	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
164	#[serde(rename_all = "camelCase", deny_unknown_fields)]
165	pub struct ReleasePrPullRequestV2 {
166	    pub number: u64,
167	    pub head_repository: GitHubRepository,
168	    pub head_branch: String,
169	    /// The pull request's current head commit. Re-observed and compared on
170	    /// every `verify_snapshot` call so a moved head is caught before the
171	    /// executor's non-compare-and-swap ref update.
172	    pub head_commit: CommitSha,
173	}
174	
175	/// A closed release-PR operation selected by Callisto.
176	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
177	#[serde(
178	    rename_all = "camelCase",
179	    rename_all_fields = "camelCase",
180	    tag = "kind",
181	    deny_unknown_fields
182	)]
183	#[non_exhaustive]
184	pub enum ReleasePrActionV2 {
185	    Noop {
186	        reason: ReleasePrNoopReasonV1,
187	    },
188	    Create {
189	        branch: String,
190	        staging_branch: String,
191	    },
192	    Update {
193	        pull_request_number: u64,
194	        branch: String,
195	        expected_head_commit: CommitSha,
196	        staging_branch: String,
197	    },
198	}
199	
200	/// Why a release-PR run is intentionally mutation-free.
201	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
202	#[serde(rename_all = "camelCase", tag = "kind", deny_unknown_fields)]
203	#[non_exhaustive]
204	pub enum ReleasePrNoopReasonV1 {
205	    NoPendingChangesets,
206	}
207	
208	/// Versioned output of managed release-PR policy derivation.
209	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
210	#[serde(try_from = "ReleasePrDecisionWireV2", rename_all = "camelCase", deny_unknown_fields)]
211	pub struct ReleasePrDecisionV2 {
212	    pub schema_version: u8,
213	    pub config: ReleasePrConfigV1,
214	    pub snapshot: ReleasePrSnapshotV2,
215	    pub action: ReleasePrActionV2,
216	}
217	
218	impl ReleasePrDecisionV2 {
219	    pub const SCHEMA_VERSION: u8 = 2;
220	
221	    /// Derives the only permitted action from fresh workspace and forge facts.
222	    pub fn derive(
223	        has_pending_changesets: bool,
224	        config: &ReleasePrConfigV1,
225	        snapshot: &ReleasePrSnapshotV2,
226	    ) -> Result<Self, ReleasePrDecisionError> {
227	        if snapshot.repository != config.repository || snapshot.base_branch != config.base_branch {
228	            return Err(ReleasePrDecisionError::SnapshotIdentityMismatch);
229	        }
230	
231	        let staging_branch = config.staging_branch();
232	        let mut eligible = Vec::new();
233	        for pr in &snapshot.open_pull_requests {
234	            if pr.head_branch == staging_branch {
235	                return Err(ReleasePrDecisionError::StagingBranchPullRequest { number: pr.number });
236	            }
237	            let shape = managed_branch_shape(&config.release_branch, &pr.head_branch)?;
238	            if shape.is_some() {
239	                if pr.head_repository != config.repository {
240	                    return Err(ReleasePrDecisionError::ForeignManagedPullRequest {
241	                        number: pr.number,
242	                        repository: pr.head_repository.clone(),
243	                    });
244	                }
245	                eligible.push(pr);
246	            }
247	        }
248	        if eligible.len() > 1 {
249	            return Err(ReleasePrDecisionError::AmbiguousManagedPullRequests { count: eligible.len() });
250	        }
251	
252	        let action = if !has_pending_changesets {
253	            ReleasePrActionV2::Noop {
254	                reason: ReleasePrNoopReasonV1::NoPendingChangesets,
255	            }
256	        } else if let Some(pr) = eligible.first() {
257	            ReleasePrActionV2::Update {
258	                pull_request_number: pr.number,
259	                branch: pr.head_branch.clone(),
260	                expected_head_commit: pr.head_commit.clone(),
261	                staging_branch: staging_branch.clone(),
262	            }
263	        } else {
264	            ReleasePrActionV2::Create {
265	                branch: config.release_branch.clone(),
266	                staging_branch,
267	            }
268	        };
269	        Ok(Self {
270	            schema_version: Self::SCHEMA_VERSION,
271	            config: config.clone(),
272	            snapshot: snapshot.clone(),
273	            action,
274	        })
275	    }
276	
277	    /// Rejects any post-decision forge state change before the executor mutates.
278	    pub fn verify_snapshot(&self, observed: &ReleasePrSnapshotV2) -> Result<(), ReleasePrDecisionError> {
279	        if observed != &self.snapshot {
280	            return Err(ReleasePrDecisionError::SnapshotChanged);
281	        }
282	        Ok(())
283	    }
284	
285	    /// Allows only the selected PR head change performed by this executor.
286	    pub fn verify_snapshot_after_update(
287	        &self,
288	        observed: &ReleasePrSnapshotV2,
289	        applied_head: &CommitSha,
290	    ) -> Result<(), ReleasePrDecisionError> {
291	        let ReleasePrActionV2::Update {
292	            pull_request_number, ..
293	        } = &self.action
294	        else {
295	            return Err(ReleasePrDecisionError::SnapshotChanged);
296	        };
297	        if Self::derive(true, &self.config, &self.snapshot)?.action != self.action {
298	            return Err(ReleasePrDecisionError::SnapshotChanged);
299	        }
300	        let mut expected = self.clone();
301	        let pr = expected
302	            .snapshot
303	            .open_pull_requests
304	            .iter_mut()
305	            .find(|pr| pr.number == *pull_request_number)
306	            .ok_or(ReleasePrDecisionError::SnapshotChanged)?;
307	        if &pr.head_commit == applied_head {
308	            return Err(ReleasePrDecisionError::SnapshotChanged);
309	        }
310	        pr.head_commit = applied_head.clone();
311	        expected.verify_snapshot(observed)
312	    }
313	}
