1	//! Interface for typed managed release-pull-request decisions, and for
2	//! building the exact forge commit-API file changes the executor submits.
3	//! `decide` and `verify` are read-only; `commit-plan` reads the Git index
4	//! and worktree but writes no forge state itself -- the executor script is
5	//! the only thing that ever calls GitHub.
6	
7	use std::process::ExitCode;
8	
9	use callisto_graph::commands::{status, StatusOptions};
10	use callisto_graph::resolver::ManifestWalkResolver;
11	use callisto_graph::{GraphError, Workspace};
12	use callisto_model::format::{parse_pre_json, PreMode};
13	use callisto_model::vcs::GitAccess;
14	use callisto_model::{
15	    ApplyPermit, CommitSha, GitHubRepository, ReleasePrActionV2, ReleasePrCommitPlanReport, ReleasePrCommitPlanV1,
16	    ReleasePrConfigV1, ReleasePrConfigWireV1, ReleasePrDecideReport, ReleasePrDecisionError, ReleasePrDecisionV2,
17	    ReleasePrDecisionWireV2, ReleasePrSnapshotV2, ReleasePrSnapshotWireV2, ReleasePrVerifyReport,
18	};
19	
20	use crate::cli::{
21	    GlobalArgs, OutputFormat, ReleasePrArgs, ReleasePrCommitPlanArgs, ReleasePrDecideArgs, ReleasePrVerifyArgs,
22	};
23	use crate::commands::read_json_arg;
24	use crate::error::CliError;
25	use crate::output::{emit_line, emit_report};
26	use crate::runner::CliCommandRunner;
27	use crate::workspace::load_workspace;
28	
29	pub fn handle(args: ReleasePrArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
30	    match args {
31	        ReleasePrArgs::Decide(args) => decide(args, global),
32	        ReleasePrArgs::Verify(args) => verify(args, global),
33	        ReleasePrArgs::CommitPlan(args) => commit_plan(args, global),
34	    }
35	}
36	
37	/// Reads `flag`'s argument (file, inline JSON, or `-` for stdin) as an unvalidated wire
38	/// value. Kept separate from the domain type's own validating constructor so a JSON parse
39	/// failure (`E281`) and a domain validation failure (its own typed `E1xx` code) are never
40	/// folded into one generic error.
41	fn read_json_arg_as<T: serde::de::DeserializeOwned>(flag: &'static str, arg: &str) -> Result<T, CliError> {
42	    let text = read_json_arg(arg)?;
43	    serde_json::from_str(&text).map_err(|error| CliError::ReleasePrArgJsonInvalid {
44	        flag,
45	        detail: error.to_string(),
46	    })
47	}
48	
49	#[derive(serde::Deserialize)]
50	#[serde(rename_all = "camelCase", deny_unknown_fields)]
51	struct ReleasePrDecisionInput {
52	    schema_version: u8,
53	    config: ReleasePrConfigWireV1,
54	    snapshot: ReleasePrSnapshotWireV2,
55	    action: ReleasePrActionV2,
56	    #[serde(default, deserialize_with = "deserialize_present")]
57	    command: Option<String>,
58	    #[serde(default, deserialize_with = "deserialize_present")]
59	    dry_run: Option<bool>,
60	}
61	
62	// Missing report metadata is allowed, but present null values are not.
63	fn deserialize_present<'de, D, T>(deserializer: D) -> Result<Option<T>, D::Error>
64	where
65	    D: serde::Deserializer<'de>,
66	    T: serde::Deserialize<'de>,
67	{
68	    T::deserialize(deserializer).map(Some)
69	}
70	
71	fn read_decision_arg(arg: &str) -> Result<ReleasePrDecisionWireV2, CliError> {
72	    let input: ReleasePrDecisionInput = read_json_arg_as("decision", arg)?;
73	    match (&input.command, input.dry_run) {
74	        (None, None) => {}
75	        (Some(command), Some(_)) if command == <ReleasePrDecideReport as callisto_model::Report>::COMMAND => {}
76	        _ => {
77	            return Err(CliError::ReleasePrArgJsonInvalid {
78	                flag: "decision",
79	                detail: "report metadata must include command=\"release-pr decide\" and a boolean dryRun".into(),
80	            });
81	        }
82	    }
83	    Ok(ReleasePrDecisionWireV2 {
84	        schema_version: input.schema_version,
85	        config: input.config,
86	        snapshot: input.snapshot,
87	        action: input.action,
88	    })
89	}
90	
91	fn verify(args: ReleasePrVerifyArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
92	    let decision_wire = read_decision_arg(&args.decision)?;
93	    let decision = ReleasePrDecisionV2::from_wire(decision_wire)?;
94	    let snapshot_wire: ReleasePrSnapshotWireV2 = read_json_arg_as("snapshot", &args.snapshot)?;
95	    let snapshot = ReleasePrSnapshotV2::from_wire(snapshot_wire)?;
96	    match args.applied_head {
97	        Some(head) => decision.verify_snapshot_after_update(&snapshot, &CommitSha::parse(&head)?)?,
98	        None => decision.verify_snapshot(&snapshot)?,
99	    }
100	    match global.format {
101	        OutputFormat::Json => emit_report(
102	            &mut std::io::stdout(),
103	            &ReleasePrVerifyReport { ok: true },
104	            global.dry_run,
105	        )?,
106	        OutputFormat::Text => emit_line("release PR decision still matches forge snapshot")?,
107	    }
108	    Ok(ExitCode::SUCCESS)
109	}
110	
111	fn decide(args: ReleasePrDecideArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
112	    let snapshot_wire: ReleasePrSnapshotWireV2 = read_json_arg_as("snapshot", &args.snapshot)?;
113	    let snapshot = ReleasePrSnapshotV2::from_wire(snapshot_wire)?;
114	    let repository =
115	        GitHubRepository::parse(&args.repository).map_err(|_error| ReleasePrDecisionError::InvalidRepository {
116	            repository: args.repository.clone(),
117	        })?;
118	    let config = ReleasePrConfigV1::new(repository, args.base_branch, args.release_branch)?;
119	
120	    let runner = CliCommandRunner;
121	    let workspace = load_workspace(global, &runner)?;
122	    reject_pre_mode(&workspace)?;
123	    let inference = crate::workspace::select_inference();
124	    let status = status(&workspace, &inference, &StatusOptions::default())?;
125	    let decision = ReleasePrDecisionV2::derive(status.has_changesets, &config, &snapshot)?;
126	
127	    match global.format {
128	        OutputFormat::Json => emit_report(
129	            &mut std::io::stdout(),
130	            &ReleasePrDecideReport { decision },
131	            global.dry_run,
132	        )?,
133	        OutputFormat::Text => render_decision(&decision)?,
134	    }
135	    Ok(ExitCode::SUCCESS)
136	}
137	
138	/// A release PR merge must consume changesets, which pre mode keeps, so it fails before a PR is opened.
139	fn reject_pre_mode(workspace: &Workspace<'_, CliCommandRunner, ManifestWalkResolver>) -> Result<(), CliError> {
140	    let path = workspace.root.join(workspace.config.pre_json_path());
141	    let text = callisto_model::strict_fs::read_optional(&path).map_err(|error| GraphError::PreJsonRead {
142	        message: error.to_string(),
143	    })?;
144	    let Some(text) = text else { return Ok(()) };
145	    let state = parse_pre_json(&text).map_err(GraphError::PreJson)?;
146	    match state.mode {
147	        PreMode::Pre => Err(CliError::ReleasePrInPreMode { tag: state.tag }),
148	        PreMode::Exit => Ok(()),
149	    }
150	}
151	
152	fn commit_plan(args: ReleasePrCommitPlanArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
153	    let base_commit = CommitSha::parse(&args.base_commit)?;
154	
155	    let start = dunce::canonicalize(&global.cwd).map_err(|source| CliError::Io {
156	        source,
157	        path: Some(global.cwd.clone()),
158	    })?;
159	    let runner = CliCommandRunner;
160	    let git = GitAccess::new(&start, &runner);
161	    let changes = git.staged_changes_since(&base_commit)?;
162	    let plan = ReleasePrCommitPlanV1::from_changes(base_commit, args.message, changes)?;
163	
164	    match args.out {
165	        Some(path) => {
166	            let permit =
167	                ApplyPermit::granted_unless_dry_run(global.dry_run).ok_or(CliError::ReleasePrCommitPlanDryRun)?;
168	            let content = serde_json::to_string_pretty(&plan).expect("commit plan serializes") + "\n";
169	            callisto_model::atomic::atomic_write(&path, &content, &permit).map_err(|source| CliError::Io {
170	                source,
171	                path: Some(path),
172	            })?;
173	        }
174	        None => emit_report(
175	            &mut std::io::stdout(),
176	            &ReleasePrCommitPlanReport { plan },
177	            global.dry_run,
178	        )?,
179	    }
180	    Ok(ExitCode::SUCCESS)
181	}
182	
183	fn render_decision(decision: &ReleasePrDecisionV2) -> Result<(), CliError> {
184	    match &decision.action {
185	        ReleasePrActionV2::Noop { reason } => emit_line(&format!("release PR: no-op ({reason:?})"))?,
186	        ReleasePrActionV2::Create { branch, staging_branch } => {
187	            emit_line(&format!("release PR: create {branch} (staging {staging_branch})"))?
188	        }
189	        ReleasePrActionV2::Update {
190	            pull_request_number,
191	            branch,
192	            expected_head_commit,
193	            staging_branch,
194	        } => emit_line(&format!(
195	            "release PR: update #{pull_request_number} ({branch}, expected head {}, staging {staging_branch})",
196	            expected_head_commit.as_str()
197	        ))?,
198	        _ => emit_line("release PR: unsupported decision")?,
199	    }
200	    Ok(())
201	}
