209	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
210	#[serde(try_from = "ReleasePrDecisionWireV2", rename_all = "camelCase", deny_unknown_fields)]
211	pub struct ReleasePrDecisionV2 {
