353	    #[error("release PR repository `{repository}` is invalid")]
354	    #[diagnostic(
355	        code(E141),
356	        help("Use the exact GitHub owner/repository identity, for example `orin-dx/callisto`.")
357	    )]
358	    InvalidRepository { repository: String },
359	    #[error("release PR {kind} `{branch}` is not a safe Git branch name")]
360	    #[diagnostic(code(E142), help("Use a non-empty Git ref name without whitespace, control characters, `..`, `@{{`, or shell-sensitive prefixes."))]
361	    InvalidBranch { kind: &'static str, branch: String },
362	    #[error("release PR snapshot contains the same pull request number more than once")]
363	    #[diagnostic(
364	        code(E143),
365	        help("Refresh the forge snapshot and pass each open pull request exactly once.")
366	    )]
367	    DuplicatePullRequestNumber,
368	    #[error("release PR snapshot does not match the configured repository or base branch")]
369	    #[diagnostic(
370	        code(E144),
371	        help(
372	            "Collect the snapshot for the configured repository and base branch immediately before calling Callisto."
373	        )
374	    )]
375	    SnapshotIdentityMismatch,
376	    #[error("managed release PR #{number} comes from foreign repository `{repository}`")]
377	    #[diagnostic(
378	        code(E145),
379	        help("Do not treat a fork branch as Callisto-managed; close or rename the lookalike before retrying.")
380	    )]
381	    ForeignManagedPullRequest { number: u64, repository: GitHubRepository },
382	    #[error("found {count} open managed release PRs")]
383	    #[diagnostic(
384	        code(E146),
385	        help("Resolve the ambiguous managed PRs manually before running the release action again.")
386	    )]
387	    AmbiguousManagedPullRequests { count: usize },
388	    #[error("managed release branch `{branch}` has an invalid SHA suffix")]
389	    #[diagnostic(
390	        code(E147),
391	        help(
392	            "Use the canonical branch or the canonical branch followed by `--` and one lowercase forty-hex commit SHA."
393	        )
394	    )]
395	    MalformedManagedBranch { branch: String },
396	    #[error("release PR snapshot changed after Callisto made its decision")]
397	    #[diagnostic(
398	        code(E148),
