451	/// keeps its own typed error instead of folding into a generic `serde` string.
452	fn check_schema_version(found: u8, expected: u8, type_name: &'static str) -> Result<(), ReleasePrDecisionError> {
453	    if found == expected {
454	        Ok(())
455	    } else {
456	        Err(ReleasePrDecisionError::UnsupportedSchemaVersion {
