464	fn validate_branch(kind: &'static str, branch: &str) -> Result<(), ReleasePrDecisionError> {
465	    let valid = !branch.is_empty()
466	        && !branch.starts_with('-')
467	        && !branch.starts_with('/')
468	        && !branch.ends_with('/')
469	        && !branch.contains("//")
470	        && !branch.contains("..")
471	        && !branch.contains("@{")
472	        && branch != "@"
473	        && branch
474	            .split('/')
475	            .all(|part| !part.starts_with('.') && !part.ends_with(".lock"))
476	        && branch.chars().all(|ch| {
477	            !ch.is_ascii_control() && !ch.is_whitespace() && !matches!(ch, '~' | '^' | ':' | '?' | '*' | '[' | '\\')
478	        });
479	    if valid {
480	        Ok(())
481	    } else {
482	        Err(ReleasePrDecisionError::InvalidBranch {
483	            kind,
484	            branch: branch.to_string(),
485	        })
486	    }
487	}
