489	fn managed_branch_shape(canonical: &str, branch: &str) -> Result<Option<()>, ReleasePrDecisionError> {
490	    if branch == canonical {
491	        return Ok(Some(()));
492	    }
493	    let Some(suffix) = branch.strip_prefix(&format!("{canonical}--")) else {
494	        return Ok(None);
495	    };
496	    if suffix.len() == 40
497	        && suffix
498	            .bytes()
499	            .all(|byte| byte.is_ascii_digit() || matches!(byte, b'a'..=b'f'))
500	    {
501	        Ok(Some(()))
502	    } else {
503	        Err(ReleasePrDecisionError::MalformedManagedBranch {
504	            branch: branch.to_string(),
505	        })
506	    }
507	}
