509	/// The regular-file Git mode `createCommitOnBranch` can express. Any other
510	/// mode (executable, symlink, submodule) is refused by [`ReleasePrCommitPlanV1::from_changes`].
511	pub const REGULAR_FILE_MODE: u32 = 0o100644;
