566	/// A closed, typed description of the exact `createCommitOnBranch` file
567	/// changes the executor may submit. Never contains a `.github/workflows/*`
568	/// path: that content is always inherited unchanged from `base_commit`.
569	#[derive(Clone, Debug, PartialEq, Eq, Serialize, JsonSchema)]
570	#[serde(rename_all = "camelCase", deny_unknown_fields)]
571	pub struct ReleasePrCommitPlanV1 {
572	    pub schema_version: u8,
573	    pub base_commit: CommitSha,
574	    pub message: String,
575	    pub additions: Vec<ReleasePrFileAdditionV1>,
576	    pub deletions: Vec<ReleasePrFileDeletionV1>,
577	    pub total_content_bytes: usize,
578	}
579	
580	impl ReleasePrCommitPlanV1 {
581	    pub const SCHEMA_VERSION: u8 = 1;
582	
583	    /// Builds a commit plan from a Git index diff. Fails closed on anything
584	    /// the forge commit API cannot faithfully express or that must never
585	    /// cross this boundary: non-regular file modes, renames/copies/type
586	    /// changes/unmerged paths, `.github/workflows/*` (and other unsafe)
587	    /// paths, an empty change set, or a payload over [`MAX_COMMIT_PLAN_BYTES`].
588	    pub fn from_changes(
589	        base_commit: CommitSha,
590	        message: String,
591	        changes: Vec<StagedChangeV1>,
592	    ) -> Result<Self, ReleasePrDecisionError> {
593	        if changes.is_empty() {
594	            return Err(ReleasePrDecisionError::EmptyCommitPlan {
595	                base_commit: base_commit.as_str().to_string(),
596	            });
597	        }
598	
599	        let mut additions = Vec::new();
600	        let mut deletions = Vec::new();
601	        let mut total_content_bytes = 0usize;
602	
603	        for change in changes {
604	            validate_commit_plan_path(&change.path)?;
605	            match change.kind {
606	                StagedChangeKindV1::Added | StagedChangeKindV1::Modified => {
607	                    let mode = change.new_mode.unwrap_or(REGULAR_FILE_MODE);
608	                    if mode != REGULAR_FILE_MODE {
609	                        return Err(ReleasePrDecisionError::UnsupportedFileMode {
610	                            path: change.path,
611	                            mode,
612	                        });
613	                    }
614	                    let contents = change.contents.unwrap_or_default();
615	                    total_content_bytes += contents.len();
616	                    additions.push(ReleasePrFileAdditionV1 {
617	                        path: change.path,
618	                        contents_base64: BASE64.encode(contents),
619	                    });
620	                }
621	                StagedChangeKindV1::Deleted => {
622	                    deletions.push(ReleasePrFileDeletionV1 { path: change.path });
623	                }
624	                StagedChangeKindV1::Renamed
625	                | StagedChangeKindV1::Copied
626	                | StagedChangeKindV1::TypeChanged
627	                | StagedChangeKindV1::Unmerged => {
628	                    return Err(ReleasePrDecisionError::UnsupportedChangeKind {
629	                        path: change.path,
630	                        kind: change.kind,
631	                    });
632	                }
633	            }
634	        }
635	
636	        if total_content_bytes > MAX_COMMIT_PLAN_BYTES {
637	            return Err(ReleasePrDecisionError::CommitPlanTooLarge {
638	                bytes: total_content_bytes,
639	                limit: MAX_COMMIT_PLAN_BYTES,
640	            });
641	        }
642	
643	        Ok(Self {
644	            schema_version: Self::SCHEMA_VERSION,
645	            base_commit,
646	            message,
647	            additions,
648	            deletions,
649	            total_content_bytes,
650	        })
651	    }
652	}
