654	impl<'de> Deserialize<'de> for ReleasePrCommitPlanV1 {
655	    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
656	    where
657	        D: Deserializer<'de>,
658	    {
659	        #[derive(Deserialize)]
660	        #[serde(rename_all = "camelCase", deny_unknown_fields)]
661	        struct Wire {
662	            schema_version: u8,
663	            base_commit: CommitSha,
664	            message: String,
665	            additions: Vec<ReleasePrFileAdditionV1>,
666	            deletions: Vec<ReleasePrFileDeletionV1>,
667	            total_content_bytes: usize,
