669	        let wire = Wire::deserialize(deserializer)?;
670	        crate::release::check_schema_version::<D::Error>(
671	            wire.schema_version,
672	            Self::SCHEMA_VERSION,
673	            "release PR commit plan",
674	        )?;
675	        Ok(Self {
676	            schema_version: wire.schema_version,
677	            base_commit: wire.base_commit,
678	            message: wire.message,
679	            additions: wire.additions,
680	            deletions: wire.deletions,
681	            total_content_bytes: wire.total_content_bytes,
682	        })
683	    }
684	}
