747	fn validate_commit_plan_path(path: &str) -> Result<(), ReleasePrDecisionError> {
748	    let forbidden = path.is_empty()
749	        || path.starts_with('/')
750	        || path.starts_with(".github/workflows/")
751	        || path == ".github/workflows"
752	        || path.starts_with(".git/")
753	        || path == ".git"
754	        || path.split('/').any(|part| part == "..")
755	        || path.contains('\0');
756	    if forbidden {
757	        Err(ReleasePrDecisionError::ForbiddenCommitPlanPath { path: path.to_string() })
758	    } else {
759	        Ok(())
760	    }
761	}
