90	    pub fn new(root: impl Into<PathBuf>, runner: &'r dyn CommandRunner) -> Self {
91	        GitAccess {
92	            runner,
93	            root: root.into(),
94	        }
95	    }
96	
97	    /// Every staged (index) change relative to `base`, resolved from the repository's toplevel rather than
98	    /// `self.root` so this works from any subdirectory. Worktree bytes are read directly (for CRLF/binary
99	    /// fidelity) and verified against the index blob sha; a mismatch fails loudly instead of returning stale bytes.
100	    pub fn staged_changes_since(&self, base: &CommitSha) -> Result<Vec<StagedChangeV1>, VcsError> {
101	        let root = self.repo_root()?;
102	
103	        let output = self.runner.run(
104	            "git",
105	            &[
106	                "diff",
107	                "--cached",
108	                "--raw",
109	                "-z",
110	                "--no-renames",
111	                "--no-abbrev",
112	                base.as_str(),
113	            ],
114	            &root,
115	        )?;
116	        if !output.success() {
117	            return Err(VcsError::Git(format!(
118	                "`git diff --cached --raw` against `{}` failed: {}",
119	                base.as_str(),
120	                output.redacted_stderr()
121	            )));
122	        }
123	
124	        let entries = parse_raw_diff_z(&output.stdout)?;
125	        let mut changes = Vec::with_capacity(entries.len());
126	        for entry in entries {
127	            let kind = staged_change_kind(entry.status);
128	            let contents = match kind {
129	                // Any other mode gets no contents so the commit plan rejects it before a symlink or submodule is read.
130	                StagedChangeKindV1::Added | StagedChangeKindV1::Modified
131	                    if entry.new_mode == Some(REGULAR_FILE_MODE) =>
132	                {
133	                    let bytes = std::fs::read(root.join(&entry.path)).map_err(|error| {
134	                        VcsError::Git(format!("could not read staged file `{}`: {error}", entry.path))
135	                    })?;
136	                    self.verify_staged_blob(&root, &entry.path, &entry.new_sha)?;
137	                    Some(bytes)
138	                }
139	                _ => None,
140	            };
141	            changes.push(StagedChangeV1 {
142	                path: entry.path,
143	                kind,
144	                new_mode: entry.new_mode,
145	                contents,
146	            });
147	        }
148	        Ok(changes)
149	    }
