151	    /// Resolves the repository's toplevel directory, whether `self.root` is that toplevel or a subdirectory.
152	    fn repo_root(&self) -> Result<PathBuf, VcsError> {
153	        self.resolved_toplevel(&format!("in `{}`", self.root.display()))
154	    }
155	
156	    /// The repository's toplevel directory, via `git rev-parse --show-toplevel` -- honors
157	    /// `GIT_DIR`/`GIT_WORK_TREE`/`GIT_CEILING_DIRECTORIES` the way `git` itself does, unlike a
158	    /// hand-rolled walk up the filesystem looking for a `.git` entry.
159	    pub fn toplevel(&self) -> Result<PathBuf, VcsError> {
160	        self.repo_root()
161	    }
162	
163	    /// The `git rev-parse --show-toplevel` resolution shared by every caller; `context` names the caller on failure.
164	    fn resolved_toplevel(&self, context: &str) -> Result<PathBuf, VcsError> {
165	        let output = self.runner.run("git", &["rev-parse", "--show-toplevel"], &self.root)?;
166	        if !output.success() {
167	            return Err(VcsError::Git(format!(
168	                "could not determine the Git repository root {context}: {}",
169	                output.redacted_stderr()
170	            )));
171	        }
172	        canonical_git_root(output.stdout_trimmed())
173	    }
