175	    /// Confirms the worktree bytes just read for `path` hash to the same blob sha the index has staged, without
176	    /// round-tripping content through a lossy `String` capture. Filters are skipped so the hash covers the bytes
177	    /// that are sent, not their clean-filtered form.
178	    fn verify_staged_blob(&self, root: &Path, path: &str, expected_sha: &str) -> Result<(), VcsError> {
179	        let output = self
180	            .runner
181	            .run("git", &["hash-object", "--no-filters", "--", path], root)?;
182	        if !output.success() {
183	            return Err(VcsError::Git(format!(
184	                "`git hash-object` failed for `{path}` in `{}`: {}",
185	                root.display(),
186	                output.redacted_stderr()
187	            )));
188	        }
189	        let actual_sha = output.stdout_trimmed();
190	        if actual_sha != expected_sha {
191	            return Err(VcsError::StagedContentMismatch {
192	                path: path.to_string(),
193	                expected_sha: expected_sha.to_string(),
194	            });
195	        }
196	        Ok(())
197	    }
