199	    /// Returns explicit, fresh Git trust evidence for a durable release.
200	    /// Errors omit raw stderr; ignored paths (build output) are allowed.
201	    pub fn observe_git_commit_trust(&self) -> Result<GitCommitTrustEvidence, VcsError> {
202	        let canonical_root = self.resolved_toplevel("for release trust")?;
203	
204	        let object_format = self
205	            .runner
206	            .run("git", &["rev-parse", "--show-object-format"], &self.root)?;
207	        if !object_format.success() || object_format.stdout_trimmed() != "sha1" {
208	            return Err(VcsError::UnsupportedObjectFormat {
209	                found: object_format.stdout_trimmed().to_string(),
210	            });
211	        }
212	        if !self.has_full_history()? {
213	            return Err(VcsError::ShallowRepository);
214	        }
215	
216	        let head = self
217	            .runner
218	            .run("git", &["rev-parse", "--verify", "HEAD^{commit}"], &self.root)?;
219	        if !head.success() {
220	            return Err(VcsError::Git(
221	                "could not resolve a commit for release trust".to_string(),
222	            ));
223	        }
224	        let head = CommitSha::parse(head.stdout_trimmed()).map_err(|error| VcsError::InvalidCommitSha {
225	            context: "for release trust".to_string(),
226	            message: error.to_string(),
227	        })?;
228	
229	        let symbolic_head = self
230	            .runner
231	            .run("git", &["symbolic-ref", "--quiet", "HEAD"], &self.root)?;
232	        let head_disposition = match symbolic_head.exit_code {
233	            Some(0) => GitHeadDisposition::Attached,
234	            Some(1) => GitHeadDisposition::Detached,
235	            _ => {
236	                return Err(VcsError::Git(
237	                    "could not determine the symbolic HEAD state for release trust".to_string(),
238	                ))
239	            }
240	        };
241	
242	        let status = self.runner.run(
243	            "git",
244	            &["status", "--porcelain=v1", "-z", "--untracked-files=all"],
245	            &self.root,
246	        )?;
247	        if !status.success() {
248	            return Err(VcsError::Git(
249	                "could not inspect the worktree for release trust".to_string(),
250	            ));
251	        }
252	        check_release_worktree_status(&status.stdout)?;
253	
254	        Ok(GitCommitTrustEvidence::new(canonical_root, head, head_disposition))
255	    }
