258	/// One `git diff --raw -z` record, before Git's single-letter status is
259	/// mapped to a [`StagedChangeKindV1`] and file contents are read.
260	struct RawDiffEntry {
261	    path: String,
262	    /// The post-image Git file mode, or `None` for a pure deletion.
263	    new_mode: Option<u32>,
264	    /// The post-image blob sha staged for this path, verified against a worktree read in `verify_staged_blob`.
265	    new_sha: String,
266	    status: char,
267	}
268	
269	/// Parses `git diff --raw -z --no-renames` output. Each record is two
270	/// `\0`-separated tokens: a `:<old-mode> <new-mode> <old-sha> <new-sha>
271	/// <status>` metadata line, then the path. `--no-renames` guarantees at
272	/// most one path per record (a rename or copy would otherwise emit two).
273	fn parse_raw_diff_z(raw: &str) -> Result<Vec<RawDiffEntry>, VcsError> {
274	    let mut entries = Vec::new();
275	    let mut tokens = raw.split('\0').filter(|token| !token.is_empty());
