38	fn commit_plan_reproduces_git_write_tree() {
39	    let dir = setup_polyglot_git_repo();
40	    let root = dir.path();
41	    let base_sha = git_ok(root, &["rev-parse", "HEAD"]);
42	
43	    // Stage an addition, a modification, a deletion, and a CRLF file.
44	    fs::write(root.join("NEW_FILE.txt"), b"brand new\n").unwrap();
45	    fs::write(
46	        root.join("crates/core/src/lib.rs"),
47	        b"pub fn hello() {\n    println!(\"hi\");\n}\n",
48	    )
49	    .unwrap();
50	    fs::remove_file(root.join("packages/web/package.json")).unwrap();
51	    fs::write(root.join("crlf.txt"), b"line one\r\nline two\r\n").unwrap();
52	    let out = git(root, &["add", "-A"]);
53	    assert!(out.status.success());
54	
55	    let expected_tree = git_ok(root, &["write-tree"]);
56	
57	    let out = Command::new(bin())
58	        .args([
59	            "--cwd",
60	            root.to_str().unwrap(),
61	            "--format",
62	            "json",
63	            "release-pr",
64	            "commit-plan",
65	            "--base-commit",
66	            &base_sha,
67	            "--message",
68	            "test commit",
69	        ])
70	        .output()
71	        .unwrap_or_else(|e| panic!("failed to spawn callisto release-pr commit-plan: {e}"));
72	    assert!(
73	        out.status.success(),
74	        "commit-plan failed: {}",
75	        String::from_utf8_lossy(&out.stderr)
76	    );
77	    let plan: serde_json::Value = serde_json::from_slice(&out.stdout).unwrap();
78	
79	    // Reconstruct the base tree into a standalone directory via `git
80	    // archive`, apply the plan's additions/deletions, and compare trees --
81	    // this never touches the original repo's own (already-staged) index.
82	    let recon = tempfile::tempdir().unwrap();
83	    let archive_out = git(root, &["archive", &base_sha]);
84	    assert!(archive_out.status.success());
85	    let tar_status = {
86	        let mut child = Command::new("tar")
87	            .args(["-x", "-C", recon.path().to_str().unwrap()])
88	            .stdin(std::process::Stdio::piped())
89	            .spawn()
90	            .unwrap();
91	        use std::io::Write;
92	        child.stdin.take().unwrap().write_all(&archive_out.stdout).unwrap();
93	        child.wait().unwrap()
94	    };
95	    assert!(tar_status.success());
96	    callisto_fixtures::git::init_repo(recon.path());
97	
98	    for addition in plan["additions"].as_array().unwrap() {
99	        let path = addition["path"].as_str().unwrap();
100	        let contents = BASE64.decode(addition["contentsBase64"].as_str().unwrap()).unwrap();
101	        let full = recon.path().join(path);
102	        if let Some(parent) = full.parent() {
103	            fs::create_dir_all(parent).unwrap();
104	        }
105	        fs::write(full, contents).unwrap();
106	    }
107	    for deletion in plan["deletions"].as_array().unwrap() {
108	        let path = deletion["path"].as_str().unwrap();
109	        let full = recon.path().join(path);
110	        if full.exists() {
111	            fs::remove_file(full).unwrap();
112	        }
113	    }
114	    git(recon.path(), &["add", "-A"]);
115	    let reconstructed_tree = git_ok(recon.path(), &["write-tree"]);
116	
117	    assert_eq!(
118	        reconstructed_tree, expected_tree,
119	        "applying the commit plan onto base_commit must reproduce the exact staged tree"
120	    );
121	
122	    let additions: std::collections::BTreeSet<&str> = plan["additions"]
123	        .as_array()
124	        .unwrap()
125	        .iter()
126	        .map(|a| a["path"].as_str().unwrap())
127	        .collect();
128	    assert!(additions.contains("NEW_FILE.txt"));
129	    assert!(additions.contains("crates/core/src/lib.rs"));
130	    assert!(additions.contains("crlf.txt"));
131	    let deletions: std::collections::BTreeSet<&str> = plan["deletions"]
132	        .as_array()
133	        .unwrap()
134	        .iter()
135	        .map(|d| d["path"].as_str().unwrap())
136	        .collect();
137	    assert!(deletions.contains("packages/web/package.json"));
138	}
